module protocol::liquidity_miner;

use std::type_name::{ Self, TypeName };

use sui::balance::Balance;
use sui::clock::Clock;
use sui::table::{ Self, Table };

use protocol::liquidity_mining_reward_manager::{ Self, PoolRewardManager };
use protocol::error;

// === Structs ===
public struct LiquidityMiner<phantom MarketType> has key, store{
    id: UID,
    deposit: Table<TypeName, PoolRewardManager>,
    borrow: Table<TypeName, PoolRewardManager>,
}

const DepositRewardType: u8 = 0;
const BorrowRewardType: u8 = 1;

// === Pubic -View Functions ===
/// Get obligation reward manager
public fun get_pool_reward_manager<MarketType, CoinType>(
    self: &LiquidityMiner<MarketType>,
    reward_type: u8,
): &PoolRewardManager {
    let coin_type = type_name::with_defining_ids<CoinType>();

    let t = self.get_reward_table<MarketType>(reward_type);
    assert!(t.contains(coin_type), error::liquidity_mining_pool_not_initialized());

    t.borrow(coin_type)
}

/// Check if borrow pool reward manager exists for CoinType
public fun has_pool_reward_manager<MarketType, CoinType>(
    self: &LiquidityMiner<MarketType>,
    reward_type: u8,
): bool {
    let coin_type = type_name::with_defining_ids<CoinType>();

    let t = self.get_reward_table<MarketType>(reward_type);
    t.contains(coin_type)
}


public(package) fun get_deposit_reward_type(): u8 { DepositRewardType }
public(package) fun get_borrow_reward_type(): u8 { BorrowRewardType }

// === Admin Function ===
public(package) fun new_liquidity_miner<MarketType>(
    ctx: &mut TxContext,
): LiquidityMiner<MarketType>{
    LiquidityMiner<MarketType>{
        id: object::new(ctx),
        deposit: table::new(ctx),
        borrow: table::new(ctx),
    }
}

public(package) fun support_coin<MarketType, CoinType>(self: &mut LiquidityMiner<MarketType>, ctx: &mut TxContext) {
    let coin_type = type_name::with_defining_ids<CoinType>();

    let mut i = 0;
    while (i < 2) {
        let t = self.get_reward_table_mut<MarketType>(i);

        assert!(!t.contains(coin_type), error::liquidity_mining_pool_initialized());
        t.add(coin_type, liquidity_mining_reward_manager::new_pool_reward_manager(ctx));

        i = i + 1;
    }
}

// Add pool rewards to pool reward managers, anyone can add
public(package) fun add_reward<MarketType, CoinType, RewardCoinType>(
    self: &mut LiquidityMiner<MarketType>,

    reward_type: u8,
    rewards: sui::coin::Coin<RewardCoinType>,

    start_time_ms: u64,
    end_time_ms: u64,

    clock: &Clock,
    ctx: &mut TxContext
){
    let pool_reward_manager = self.get_reward_manager_mut<MarketType, CoinType>(reward_type);
    pool_reward_manager.add_pool_reward(rewards.into_balance(), start_time_ms, end_time_ms, clock, ctx);
}

/// Cancel rewards 
public(package) fun cancel_reward<MarketType, CoinType, RewardCoinType>(
    self: &mut LiquidityMiner<MarketType>,
    reward_type: u8,
    reward_index: u64,
    clock: &Clock,
): Balance<RewardCoinType>{
    let pool_reward_manager = self.get_reward_manager_mut<MarketType, CoinType>(reward_type);
    pool_reward_manager.cancel_pool_reward<RewardCoinType>(reward_index, clock)
}

// Close rewards 
public(package) fun close_reward<MarketType, CoinType, RewardCoinType>(
    self: &mut LiquidityMiner<MarketType>,
    reward_type: u8,
    reward_index: u64,
    clock: &Clock,
): Balance<RewardCoinType>{
    let pool_reward_manager = self.get_reward_manager_mut<MarketType, CoinType>(reward_type);
    pool_reward_manager.close_pool_reward<RewardCoinType>(reward_index, clock)
}


public(package) fun update_obligation_reward_manager<MarketType, CoinType>(
    self: &mut LiquidityMiner<MarketType>,
    reward_type: u8,
    obligation_id: ID,
    new_share: u64,
    clock: &Clock,
){
    let pool_reward_manager = self.get_reward_manager_mut<MarketType, CoinType>(reward_type);

    if (!pool_reward_manager.borrow_obligation_reward_managers().contains(obligation_id)){
        pool_reward_manager.new_obligation_reward_manager(obligation_id, clock);
    };

    pool_reward_manager.change_obligation_reward_manager_share(obligation_id, new_share, clock);
}

public(package) fun claim_rewards<MarketType, CoinType, RewardCoinType>(
    self: &mut LiquidityMiner<MarketType>,

    reward_type: u8,
    obligation_id: ID,

    clock: &Clock,
    reward_index: u64,
): Balance<RewardCoinType>{
    let pool_reward_manager = self.get_reward_manager_mut<MarketType, CoinType>(reward_type);
    let claimed_reward = pool_reward_manager.claim_rewards(obligation_id, clock, reward_index);
    claimed_reward
}

fun get_reward_table_mut<MarketType>(self: &mut LiquidityMiner<MarketType>, reward_type: u8): &mut Table<TypeName, PoolRewardManager> {
    match (reward_type) {
        DepositRewardType => &mut self.deposit,
        BorrowRewardType => &mut self.borrow,
        // sanity check only
        _ => abort(0),
    }
}

fun get_reward_manager_mut<MarketType, CoinType>(self: &mut LiquidityMiner<MarketType>, reward_type: u8): &mut PoolRewardManager {
    let coin_type = type_name::with_defining_ids<CoinType>();

    let t = self.get_reward_table_mut<MarketType>(reward_type);
    assert!(t.contains(coin_type), error::liquidity_mining_pool_not_initialized());

    t.borrow_mut(coin_type)
}

fun get_reward_table<MarketType>(self: &LiquidityMiner<MarketType>, reward_type: u8): &Table<TypeName, PoolRewardManager> {
    match (reward_type) {
        DepositRewardType => &self.deposit,
        BorrowRewardType => &self.borrow,
        // sanity check only
        _ => abort(0),
    }
}

