   161→public(package) fun add_pool_reward<CoinType>(
   162→    pool_reward_manager: &mut PoolRewardManager,
   163→    rewards: Balance<CoinType>,
   164→    start_time_ms: u64,
   165→    end_time_ms: u64,
   166→    clock: &Clock,
   167→    ctx: &mut TxContext
   168→){
   169→    assert!(start_time_ms >= clock.timestamp_ms(), error::liquidity_mining_invalid_start_time());
   170→    assert!(end_time_ms - start_time_ms >= MIN_REWARD_PERIOD_MS, error::liquidity_mining_invalid_time());
   171→
   172→    let pool_reward = PoolReward {
   173→        id: object::new(ctx),
   174→        pool_reward_manager_id: object::id(pool_reward_manager),
   175→        coin_type: type_name::with_defining_ids<CoinType>(),
   176→        start_time_ms,
   177→        end_time_ms,
   178→        total_rewards: rewards.value(),
   179→        allocated_rewards: float::from(0),
   180→        cumulative_rewards_per_share: float::from(0),
   181→        num_obligation_reward_managers: 0,
   182→        additional_fields: {
   183→            let mut bag = bag::new(ctx);
   184→            bag.add(RewardBalance<CoinType>{}, rewards);
   185→            bag
   186→        },
   187→    };
   188→
   189→    let i = find_available_index(pool_reward_manager);
   190→    assert!(i < MAX_REWARDS, error::liquidity_mining_max_concurrent_pool_rewards_violated());
   191→    
   192→    let optional_pool_reward = pool_reward_manager.pool_rewards.borrow_mut(i);
   193→    optional_pool_reward.fill(pool_reward);
   194→}
